export function tapeTicks(limit_seconds: number) {
  if (limit_seconds <= 0) return [];
  const step = limit_seconds > 30 ? 2 : 1;
  const major = limit_seconds > 30 ? 10 : 5;
  const ticks: { position: number; major: boolean }[] = [];
  for (let second = 0; second <= limit_seconds; second += step) {
    ticks.push({ position: second / limit_seconds, major: second % major === 0 });
  }
  return ticks;
}
